const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define the two locations
  const laPoint = ee.Geometry.Point([-118.2436826460509, 33.97811334086217]);
  const sdPoint = ee.Geometry.Point([-117.15380986802357, 32.7358717958782]);

  // Time period: 2018-2019
  const startDate = '2018-01-01';
  const endDate = '2020-01-01';

  // Get Sentinel-5P NO2 data
  const no2Collection = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_NO2')
    .filterDate(startDate, endDate)
    .select('NO2_column_number_density');

  // Check collection size
  const collectionSize = no2Collection.size().getInfo();
  console.log(`Total NO2 images: ${collectionSize}`);

  if (collectionSize === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // Calculate mean NO2 for the entire period
  const meanNo2 = no2Collection.mean();

  // Extract values at both points
  const laValue = meanNo2.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: laPoint,
    scale: 1000,
    maxPixels: 1e9
  }).get('NO2_column_number_density');

  const sdValue = meanNo2.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: sdPoint,
    scale: 1000,
    maxPixels: 1e9
  }).get('NO2_column_number_density');

  // Get values and check for validity
  const laNo2 = laValue.getInfo();
  const sdNo2 = sdValue.getInfo();

  console.log(`LA NO2: ${laNo2 !== null ? laNo2.toFixed(6) : 'null'}`);
  console.log(`SD NO2: ${sdNo2 !== null ? sdNo2.toFixed(6) : 'null'}`);

  // Check for invalid data
  if (laNo2 === null || sdNo2 === null || isNaN(laNo2) || isNaN(sdNo2)) {
    console.log("<answer>C3</answer>");
    return;
  }

  // Check if values are reasonable (NO2 should be positive and typically < 0.001 mol/m²)
  if (laNo2 < 0 || laNo2 > 0.01 || sdNo2 < 0 || sdNo2 > 0.01) {
    console.log("<answer>C3</answer>");
    return;
  }

  // Compare values and output result
  if (laNo2 > sdNo2) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
